current = cls.fromdatetime(start)
i = 0

while current <= end and i < limit:
    i += 1
    yield current

    values = [getattr(current, f) for f in cls._ATTRS]
    current = cls(*values, tzinfo=tzinfo).shift(
        **{frame_relative: relative_steps}
    )

